prompt:
Implement only the behavior required below in the frozen browser page. Replace the single /* MODEL_BEHAVIOR */ marker with vanilla JavaScript statements. Use the provided app API and do not change any other byte of the page. Return only the complete HTML page.

Requirement:
When none of the three fields (% Complete, Work, or Remaining Work) have values set, the field you fill in first will determine how the others are calculated:

- If you enter Work only, % Complete will be set to 0%.

Frozen page:
<!doctype html><html><head><meta charset="utf-8"><title>Work package</title>
<style>body{font:16px system-ui;max-width:850px;margin:2rem auto;padding:1rem}label{display:block;margin:.7rem}button,input{font:inherit;padding:.4rem}</style></head>
<body><main><h1>Work package</h1><label>Work <input aria-label="Work"></label><label>Remaining Work <input aria-label="Remaining Work"></label><label>% Complete <input aria-label="% Complete"></label><button>Save</button></main>
<script>
let saveBehavior=null;
const fields=Object.freeze({work:document.querySelector('[aria-label="Work"]'),remaining:document.querySelector('[aria-label="Remaining Work"]'),percent:document.querySelector('[aria-label="% Complete"]')});
const app=Object.freeze({
  onSave(handler){if(typeof handler!=='function'||saveBehavior)throw new Error('invalid save behavior');saveBehavior=handler},
  values(){return {work:fields.work.value,remaining:fields.remaining.value,percent:fields.percent.value}},
  apply(values){for(const key of ['work','remaining','percent'])if(Object.hasOwn(values,key))fields[key].value=String(values[key])}
});
document.querySelector('button').addEventListener('click',()=>{if(saveBehavior){const next=saveBehavior(app.values());if(next&&typeof next==='object')app.apply(next)}});
/* MODEL_BEHAVIOR */
</script></body></html>
